    "title": "关于举行2026年全国大学生结构设计竞赛西安交通大学校赛暨陕西省省赛选拔赛的通知",
    "date": "2026-03-02",
    "url": "http://pec.xjtu.edu.cn/info/1191/5061.htm",
    "competition": "全国大学生结构设计竞赛",
    "moeNo": 9,
    "site": "实践教学中心",
    "sourceLabel": "实践教学中心",
    "dateUnavailableReason": "",
    "isCompetition": true,
