   "fetchStatus": "success",
   "fetchError": "",
   "fetchedAt": "2026-11-05T14:42:12.739081+00:00",
   "identitySources": [
    {
     "raw": "2018年11月14日周三晚，西安交通大学第三届主持人大赛初赛在党员之家圆满落下了帷幕。",
     "location": {
      "type": "body",
      "start": 0,
      "end": 44
     }
    },
    {
     "raw": "西安交通大学第三届主持人大赛以“普通话诵经典，规范字书中华”为主题，由校团委、教务处共同主办，学生艺术团主持团承办，旨在深入贯彻落实习近平新时代中国特色社会主义思想和党的十九大精神，落实中共中央办公厅、国务院办公厅印发的《关于实施中华优秀传统文化传承发展工程的意见》，为我校打造“腹有诗书气自华”的王牌主持。",
     "location": {
      "type": "body",
      "start": 76,
      "end": 230
     }
    }
   ],
   "noticeReferences": [],
