   "fetchStatus": "success",
   "fetchError": "",
   "fetchedAt": "2026-11-05T14:43:00.277436+00:00",
   "identitySources": [
    {
     "raw": "根据国家“节能减排全民行动计划”和教育部“关于开展节能减排学校行动的通知”（教高司函【2008】40号）的有关精神，教育部高教司主办并委托教育部高等学校能源动力学科教学指导委员会承办“全国大学生节能减排社会实践与科技竞赛”。",
     "location": {
      "type": "body",
      "start": 68,
      "end": 180
     }
    },
    {
     "raw": "为备战全国第五届大学生节能减排社会实践与科技竞赛，深入开展节能减排行动，引导和激励学生实事求是、勇于创新、提高素质，培养学生创新精神和实践能力；",
     "location": {
      "type": "body",
      "start": 360,
      "end": 432
     }
    },
    {
     "raw": "3、作品终审：专家组委会将于2012年5月中旬对入围竞赛作品进行终审与答辩，提出改进意见并确定最终选拔后参加全国赛的名单。",
     "location": {
      "type": "body",
      "start": 1350,
      "end": 1411
     }
    }
   ],
